 t=re.sub(r'(?<=[0-9])(?=(?:calls|roots|worlds|conditions|qualification|main|correct|wrong|refer|done|running|planned|minutes|points|total|safe|model|fields|calls/s|input|tokens|output|episodes|cases|members)\b)',' ',t)
 t=re.sub(r'(?<=[A-Za-z])(?=T\+)',' ',t)
 t=re.sub(r'(?<=[,:;])(?=[A-Za-z0-9$])',' ',t)
 t=t.replace('≥0.75calls/s','≥ 0.75 calls/s').replace('below5','below 5').replace('7/8','7/8').replace('a95%','a 95%')
 return t
