nav=''.join(f'<a href="#s{i}">{esc(s["title"])}</a>' for i,s in enumerate(P['sections']))
body=''.join(f'<section id="s{i}"><small>{esc(s["group"])}</small><h2>{esc(s["title"])}</h2><p>{esc(s["body"])}</p></section>' for i,s in enumerate(P['sections']))
