roles=''.join(f'<details><summary>{esc(r["title"])}</summary><p>{esc(r["owns"])}</p><button onclick="copyRole({i},this)">Copy session brief</button><pre id="role{i}">{esc(r["prompt"])}</pre></details>' for i,r in enumerate(P['roles']))
evidence=''.join('<details class="evidence"><summary>'+esc(e['name'])+' <span>'+esc(e['verdict'])+'</span></summary><p>'+esc(e['result'])+'</p><p><b>Units:</b> '+esc(e['sample'])+'</p><p>'+esc(e['reading'])+'</p><p><b>Limit:</b> '+esc(e['limit'])+'</p><small>'+esc(e['asof'])+'</small><p>'+ ' · '.join('<a href="'+esc(s['url'])+'">'+esc(s.get('path','Source').split('/')[-1])+'</a>' for s in e.get('sources',[]))+'</p></details>' for e in P['evidence'])
refs=''.join(f'<li><a href="{esc(s["url"])}">{esc(s["label"])}</a></li>' for s in P['sources'])
css='''*{box-sizing:border-box}body{margin:0;background:#f4f1e9;color:#182b2c;font:16px/1.65 Georgia,serif}header,main{max-width:1180px;margin:auto;padding:32px}header{padding-top:52px}h1{font-size:38px;line-height:1.16;max-width:800px;margin:12px 0}h2{font:600 24px/1.3 system-ui;margin:6px 0 16px}p{max-width:920px}small,.eyebrow,nav,button,summary,th{font-family:system-ui}small{color:#506464}a{color:#16635e}nav{display:flex;gap:16px;flex-wrap:wrap;font-size:14px;padding:18px 0;border-block:1px solid #aab8b3}.status{font:12px system-ui;letter-spacing:1px}.lede{font-size:21px;max-width:920px}.numbers{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid #aab8b3;margin:26px 0}.numbers div{padding:18px;border-right:1px solid #aab8b3}.numbers strong{display:block;font:600 27px system-ui}.numbers span{font:13px system-ui}section{padding:34px 0;border-bottom:1px solid #b8c3bd}table{border-collapse:collapse;font:14px/1.55 system-ui;width:100%}td,th{padding:14px;text-align:left;vertical-align:top;border-bottom:1px solid #b8c3bd}th:first-child{width:150px}details{padding:18px 0;border-bottom:1px solid #b8c3bd}summary{cursor:pointer;font-weight:600}summary span{font-size:12px;font-weight:400;display:block;color:#506464}pre{white-space:pre-wrap;font:14px/1.65 system-ui;background:#e8ebe3;padding:20px}button{padding:10px 14px;border:1px solid #16635e;background:#16635e;color:white;cursor:pointer}input{font:16px system-ui;padding:12px;border:1px solid #aab8b3;width:100%;max-width:480px}.calculator{display:flex;gap:24px;flex-wrap:wrap;align-items:center;font:14px system-ui}.calculator input{width:100px}.toc{max-height:240px;overflow:auto;column-count:2;font:14px/1.6 system-ui}.toc a{display:block;margin-bottom:8px}footer{padding:32px 0;color:#506464;font:13px system-ui}@media(max-width:700px){header,main{padding:22px}h1{font-size:30px}.numbers{grid-template-columns:1fr 1fr}.toc{column-count:1}table{font-size:12px}td,th{padding:8px}}'''
doc=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(P['title'])}</title><style>{css}</style><header><div class="eyebrow">SWARM LAB / RESEARCH PROGRAM / 04 OCTOBER 2026</div><h1>{esc(P['title'])}</h1><p class="lede">{esc(P['recommendation'])}</p><p class="status">{esc(P['status'])}</p><div class="numbers"><div><strong>7 hours</strong><span>Hard release deadline</span></div><div><strong>48 roots</strong><span>Independent units</span></div><div><strong>5,760</strong><span>Main call ceiling</span></div><div><strong>5 sessions</strong><span>One dispatch authority</span></div></div><nav><a href="#evidence">Evidence review</a><a href="#schedule">Seven-hour clock</a><a href="#roles">Session briefs</a><a href="#s6">Experiment</a><a href="#s18">Fallback</a><a href="#refs">Sources</a></nav><p><small>{esc(P['cutoff'])}</small></p></header><main><details><summary>Full program contents</summary><div class="toc">{nav}</div></details><section id="schedule"><h2>Seven-hour clock</h2><table><thead><tr><th>Relative time</th><th>Work</th><th>Release gate</th></tr></thead><tbody>{schedule}</tbody></table><p class="calculator"><label>Accounted calls per second <input id="rate" type="number" min="0.1" max="50" step="0.05" value="0.75" oninput="estimate()"></label><output id="estimate"></output></p><small>Planning sensitivity:5,760calls ÷ sustained rate ×1.25 overhead. Excludes pre-run qualification and reporting. Not a measured runtime.</small></section>{body}<section id="roles"><h2>Five copy-ready session briefs</h2><p>Use these after admission of the named program. They allocate ownership and stop conditions; they do not start sessions here.</p>{roles}</section><section id="evidence"><h2>Portfolio evidence and decisions</h2><p>The complete 15-entry prior review is retained, followed by 6 newer updates. Superseded observations are labeled by date/version; this is 21 review entries, not 21 independent experiment families.</p><input aria-label="Filter evidence" placeholder="Filter by study or finding" oninput="filterEvidence(this.value)">{evidence}</section><section id="refs"><h2>External sources</h2><ul>{refs}</ul><p>Local input snapshots and hashes are in inputs/source-index.json beside the program. The full original larger proposal is retained as an input. This document reports a design and historical findings; it contains no new experimental result.</p></section><footer>Prepared locally in the Swarm Lab Flight Deck project. Scientific implementation, qualification and launch remain future work.</footer></main><script>function estimate(){{let r=Number(document.getElementById('rate').value);document.getElementById('estimate').textContent=r>0?(5760/r*1.25/60).toFixed(0)+' minutes including 25% overhead':'Enter a positive rate';}}function filterEvidence(q){{document.querySelectorAll('.evidence').forEach(e=>e.hidden=!e.textContent.toLowerCase().includes(q.toLowerCase()));}}async function copyRole(i,b){{const t=document.getElementById('role'+i).textContent;try{{await navigator.clipboard.writeText(t);b.textContent='Copied';}}catch(e){{const r=document.createRange();r.selectNodeContents(document.getElementById('role'+i));const s=window.getSelection();s.removeAllRanges();s.addRange(r);b.textContent='Selected — copy text';}}}}estimate();</script></html>'''
(B/'program.html').write_text(doc)

