tsx='''import {useState,useHostTheme,Stack,Row,H1,H2,Text,Button,Table,Callout,Divider} from "cursor/canvas";
const data=__DATA__;
export default function OvernightProgram(){const theme=useHostTheme();const [tab,setTab]=useState("Program");const [rate,setRate]=useState(0.75);return <Stack gap={20} style={{padding:24,color:theme.text.primary}}><Text>SWARM LAB · 04 OCTOBER 2026</Text><H1>{data.title}</H1><Text>{data.recommendation}</Text><Callout>{data.status}</Callout><Row gap={16} wrap>{["Program","Evidence","Schedule","Session briefs"].map(t=><Button key={t} onClick={()=>setTab(t)}>{t}</Button>)}</Row><Text>7 hours · 48 independent roots · 5,760 main calls · 5 managing sessions</Text><Divider/>{tab==="Program"&&data.sections.map((s,i)=><Stack key={i} gap={8}><Text>{s.group}</Text><H2>{s.title}</H2><Text>{s.body}</Text><Divider/></Stack>)}{tab==="Evidence"&&<Stack gap={16}><Text>{data.cutoff}</Text>{data.evidence.map((e,i)=><details key={i}><summary style={{cursor:"pointer",fontWeight:600}}>{e.name} · {e.verdict}</summary><p>{e.result}</p><p>{e.sample}</p><p>{e.reading}</p><p>Limit: {e.limit}</p><p>{e.asof}</p>{e.sources.map((s,j)=><p key={j}><a href={s.url} style={{color:theme.accent.primary}}>{s.path}</a></p>)}</details>)}</Stack>}{tab==="Schedule"&&<Stack gap={20}><H2>Seven-hour clock</H2><Table headers={["Time","Work","Gate"]} rows={data.schedule.map(s=>[s.time,s.work,s.gate])}/><label>Accounted calls per second <input type="number" min={0.1} step={0.05} value={rate} onChange={e=>setRate(Number(e.target.value))}/></label><Text>{rate>0?(5760/rate*1.25/60).toFixed(0)+" minutes for main collection including 25% overhead":"Enter a positive rate"}. This is a planning sensitivity, excluding qualification and reporting.</Text></Stack>}{tab==="Session briefs"&&data.roles.map((r,i)=><details key={i}><summary style={{cursor:"pointer",fontWeight:600}}>{r.title}</summary><p>{r.owns}</p><textarea readOnly aria-label={r.title+" brief"} value={r.prompt} style={{width:"100%",height:300,padding:12,color:theme.text.primary,background:theme.fill.secondary}}/></details>)}<Divider/><H2>Sources and portable version</H2>{data.sources.map(s=><a key={s.url} href={s.url} style={{color:theme.accent.primary}}>{s.label}</a>)}<Text>The portable HTML version and frozen input snapshots are in the Swarm Lab overnight-program-2026-10-04 study notes. No new calls or loops were started.</Text></Stack>}
'''.replace('__DATA__',data)
